mutations.find:
if (typeof value !== "number" || !Number.isInteger(value) || value < 1)
  throw new Error(`spawn(${persona}): supervise.restarts must be a positive integer, got ${JSON.stringify(value)}`);
restarts = value;

mutations.replace:
if (typeof value === "string" && /^[0-9]+$/.test(value)) restarts = Number(value);
else if (typeof value !== "number" || !Number.isInteger(value) || value < 1)
  throw new Error(`spawn(${persona}): supervise.restarts must be a positive integer, got ${JSON.stringify(value)}`);
else restarts = value;
